#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_products_eta.py — Kit 29g [cj-freeship] — «توصيل مجاني» بارز بلا أزرار
رقعة فرونت-برك — ملف واحد (standalone):
  • app/components/DeliveryEstimator.tsx → تعويض كامل بـ v5 [cj-eta-v5]

الأمان:
  • fail-closed — أي شك → exit 1 بلا حتى كتابة + diag
  • نسخة احتياطية .bak-kit29g (أول مرة برك — الأصل ديما محفوظ)
  • idempotent — [cj-eta-v5] موجود → skip نظيف
  • ترقية أوتوماتيكية من [cj-eta-v4] (kit 29f) ولا [cj-eta-v3] (kit 29e v2)
    ولا [cj-eta] (v1 القديمة)
"""
import base64, json, os, shutil, sys, time

MARKER_NEW = "[cj-eta-v5]"
OLD_MARKERS = ["[cj-eta-v4]", "[cj-eta-v3]", "[cj-eta]"]
BACKUP = ".bak-kit29g"
SKIP_DIRS = {"node_modules", ".next", ".git", ".vercel", ".turbo", "dist", "build", "coverage", ".sentinel"}
F = json.loads("""{"est_v5": ""}""")

def B(key):
    return base64.b64decode(F[key]).decode("utf-8")

def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()

def write(path, content):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)

def find_file(names, roots):
    for root in roots:
        if not os.path.isdir(root):
            continue
        for nm in names:
            for dirpath, dirnames, filenames in os.walk(root):
                dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
                if nm in filenames:
                    return os.path.join(dirpath, nm)
    return None

def diag(est_path, est_content):
    try:
        d = "kit29g-diag"
        os.makedirs(d, exist_ok=True)
        if est_path and est_content is not None:
            with open(os.path.join(d, "DeliveryEstimator.current.tsx"), "w", encoding="utf-8") as f:
                f.write(est_content)
        pdc = find_file(["ProductDetailsClient.tsx", "ProductDetailsClient.jsx"], ["app", "components", "src"])
        if pdc:
            shutil.copy2(pdc, os.path.join(d, "ProductDetailsClient.current.tsx"))
        with open(os.path.join(d, "manifest.txt"), "w", encoding="utf-8") as f:
            f.write("time: " + time.strftime("%Y-%m-%d %H:%M:%S") + "\n")
            f.write("cwd: " + os.getcwd() + "\n")
            f.write("est_path: " + str(est_path) + "\n")
        print("↳ نسخنا الملفات الحالية ديالك فـ kit29g-diag/ — صيفطهم ليّا نرجعو ليك رقعة مخصصة 100%")
    except Exception as e:
        print("↳ diag فشل هو نفسو: " + str(e))

print("══ Kit 29g [cj-freeship] — «توصيل مجاني» بارز بلا أزرار (v5) ══")
print("")

# ── 1) جذر الفرونت ──
if not (os.path.exists("next.config.ts") or os.path.exists("next.config.js")):
    print("❌ خدم من جذر الفرونت (المجلد اللي فيه next.config.ts)")
    print("   مثال:  cd path-to-frontend && python patch_products_eta.py")
    sys.exit(1)

# ── 2) لقاء المكوّن ──
est_path = find_file(["DeliveryEstimator.tsx", "DeliveryEstimator.jsx"], ["app", "components", "src"])

est_content = None
if est_path:
    try:
        est_content = read(est_path)
    except Exception as e:
        print("❌ ما قدرتش نقرا " + est_path + " : " + str(e))
        diag(est_path, None)
        sys.exit(1)

if not est_path or est_content is None:
    print("❌ DeliveryEstimator ما لقيتوش حتى فالتسير (app/, components/, src/)")
    diag(None, None)
    sys.exit(1)

print("  📂 المكوّن: " + est_path)

# ── 3) الحالة ──
if MARKER_NEW in est_content:
    print("  ⏭️ v5 [cj-eta-v5] مركّب مسبقاً — idempotent skip (والو ما تبدل)")
    sys.exit(0)

low = est_content.lower()
if ("deliveryestimator" not in low) and ("delivery" not in low):
    print("❌ " + est_path + " مامشبهش لمكوّن delivery")
    diag(est_path, est_content)
    sys.exit(1)

mode_upgrade = any(m in est_content for m in OLD_MARKERS)
if mode_upgrade:
    print("  🔄 لقيت نسخة قديمة (أزرار v4 ولا v3 ولا v1) — ترقية لـ v5 [cj-freeship]")

# ── 4) backup + تعويض ──
bak = est_path + BACKUP
if os.path.exists(bak):
    print("  ♻ backup محفوظ مسبقاً (" + os.path.basename(bak) + " — الأصل ديما معانا)")
else:
    shutil.copy2(est_path, bak)
    print("  ♻ backup ← " + os.path.basename(bak))

write(est_path, B("est_v5"))
print("  ✚ DeliveryEstimator v5 [cj-freeship] — 🚚 Free Delivery بارز فوق كلشي")
print("     الأزرار تُحيدو · أسماء القنوات والأثمنة سِر داخلي 100%")
print("     نافذة CJ الحقيقية (القناة اللي المتجر كيشحن بيها) · fallback واقعي 2-4 أسابيع")

# ── 5) معلومات ──
pdc = find_file(["ProductDetailsClient.tsx", "ProductDetailsClient.jsx"], ["app", "components", "src"])
if pdc:
    print("  ℹ️ PDC (" + pdc + ") ما تلمسش — المكوّن مستقل كيخدم مع أي شكل ديالو")
else:
    print("  ℹ️ PDC مالقيتوش فالمسارات المعتادة — عادي، المكوّن مستقل")

print("")
print("[NEXT] npm run build (خاصو يعدّي بلا أخطاء) ثم deploy")
print("      من بعد: حل أي صفحة /products/:id من بلادك — غادي تشوف 🚚 Free Delivery بارز")
sys.exit(0)
